<?php
header('Content-Type: application/json');
/* Menu imagery and stock should refresh immediately after an admin update. */
header('Cache-Control: no-store, max-age=0');
header('Access-Control-Allow-Origin: http://localhost');
header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');
header('Access-Control-Allow-Headers: Content-Type');
header('Access-Control-Allow-Credentials: true');
if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') { http_response_code(204); exit; }
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/require_login.php';
require_once __DIR__ . '/recipe-stock.php';

// GET (menu browsing) stays public — customers browse the menu without logging in.
// Viewing archived items and every write is menu management: Admin only.
$action = $_GET['action'] ?? '';
if ($_SERVER['REQUEST_METHOD'] !== 'GET' || $action === 'archive') {
    requireRole(['Admin']);
}

// menu_items.category_id is a FK -> menu_categories.id, but the frontend (app.js)
// sends/expects a category NAME string in item objects, same as the old pos_items.category
// column. These two helpers translate at the API boundary so the JSON contract doesn't change.

function categoryIdByName($conn, $name) {
    $name = trim($name);
    if ($name === '') return null;
    $stmt = $conn->prepare('SELECT id FROM menu_categories WHERE name = ? AND deleted_at IS NULL LIMIT 1');
    $stmt->bind_param('s', $name);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    return $row ? (int)$row['id'] : null;
}

function categoryNameById($conn, $id) {
    if (!$id) return '';
    $stmt = $conn->prepare('SELECT name FROM menu_categories WHERE id = ?');
    $stmt->bind_param('i', $id);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    return $row ? $row['name'] : '';
}

// Attach a 'category' name string to each row (in place of the raw category_id) so
// every JSON response keeps returning what the frontend has always expected.
function attachCategoryNames($conn, $rows) {
    if (empty($rows)) return $rows;
    $ids = array_unique(array_filter(array_map(function($r) { return $r['category_id'] ?? null; }, $rows)));
    $names = [];
    if ($ids) {
        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $types = str_repeat('i', count($ids));
        $stmt = $conn->prepare("SELECT id, name FROM menu_categories WHERE id IN ($placeholders)");
        $stmt->bind_param($types, ...array_values($ids));
        $stmt->execute();
        foreach ($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $c) { $names[$c['id']] = $c['name']; }
    }
    foreach ($rows as &$r) {
        $r['category'] = $names[$r['category_id']] ?? '';
    }
    return $rows;
}

/*
 * Seeded menu records in older installations do not always have their image
 * column populated. These compact WebP data URIs are a display-only fallback
 * for the known seed products, so product photography works even before the
 * optional pos/uploads image folder is copied to an existing installation.
 * Uploaded/admin-selected database images always win; no record is written.
 */
function applyBuiltInMenuImages($rows) {
    $photos = [
        'iced caramel latte' => 'data:image/webp;base64,',
        'mocha frappe' => 'data:image/webp;base64,',
        'test' => 'data:image/webp;base64,',
        'cupcake' => 'data:image/webp;base64,',
        'cafe latte' => 'data:image/webp;base64,',
        'caramel latte' => 'data:image/webp;base64,',
        'caramel macchiato' => 'data:image/webp;base64,',
        'espresso' => 'data:image/webp;base64,',
        'matcha latte' => 'data:image/webp;base64,',
        'meal set' => 'data:image/webp;base64,',
        'butter croissant' => 'data:image/webp;base64,',
    ];
    foreach ($rows as &$row) {
        $configuredImage = trim((string)($row['image'] ?? ''));
        /* Keep a valid custom upload or existing data URI. If an old database
           path points to a file that is absent on this installation, replace
           it with the embedded seed photo instead of letting the browser show
           a broken image and fall back to the emoji. */
        $hasUsableImage = $configuredImage !== '' && (
            strpos($configuredImage, 'data:image/') === 0 ||
            preg_match('~^https?://~i', $configuredImage) ||
            is_file(__DIR__ . '/../' . ltrim($configuredImage, '/'))
        );
        if ($hasUsableImage) continue;
        $key = strtolower(trim((string)($row['name'] ?? '')));
        if (isset($photos[$key])) $row['image'] = $photos[$key];
    }
    unset($row);
    return $rows;
}

$method = $_SERVER['REQUEST_METHOD'];
$action = $_GET['action'] ?? '';

switch ($method) {
    case 'GET':    if ($action === 'featured')  { getFeaturedItems(); } elseif ($action === 'archive') { getArchivedItems(); } else { getAllItems(); } break;
    case 'POST':   if (isset($_GET['_update']) && $_GET['_update'] === '1' && isset($_GET['id'])) { updateItem(); } else { createItem(); } break;
    case 'PUT':    if ($action === 'restore') { restoreItem(); } else { updateItem(); } break;
    case 'DELETE': if ($action === 'permanent') { permanentDeleteItem(); } else { archiveItem(); } break;
    default: echo json_encode(['error' => 'Method not allowed']);
}

function handleImageUpload($existingImage = '') {
    if (empty($_FILES['image']['tmp_name'])) return $existingImage;
    $file = $_FILES['image'];
    if (!in_array($file['type'], ['image/jpeg','image/png','image/gif','image/webp'])) { http_response_code(400); echo json_encode(['error' => 'Only JPG, PNG, GIF, or WEBP allowed.']); exit; }
    if ($file['size'] > 5*1024*1024) { http_response_code(400); echo json_encode(['error' => 'Image must be under 5 MB.']); exit; }
    $uploadDir = __DIR__ . '/../uploads/items/';
    if (!is_dir($uploadDir)) mkdir($uploadDir, 0755, true);
    $ext = pathinfo($file['name'], PATHINFO_EXTENSION);
    $filename = uniqid('item_', true) . '.' . strtolower($ext);
    $dest = $uploadDir . $filename;
    if (!move_uploaded_file($file['tmp_name'], $dest)) { http_response_code(500); echo json_encode(['error' => 'Failed to save image.']); exit; }
    if ($existingImage) { $old = __DIR__ . '/../' . $existingImage; if (file_exists($old)) @unlink($old); }
    return 'uploads/items/' . $filename;
}

function getAllItems() {
    $conn = getDB();
    refreshMenuStockFromRecipes($conn); // menu grid always shows live makeable counts
    $category = $_GET['category'] ?? '';
    if ($category) {
        $catId = categoryIdByName($conn, $category);
        if ($catId === null) { echo json_encode(['success' => true, 'data' => []]); $conn->close(); return; }
        $stmt = $conn->prepare('SELECT * FROM menu_items WHERE category_id = ? AND deleted_at IS NULL ORDER BY name ASC');
        $stmt->bind_param('i', $catId);
    } else {
        $stmt = $conn->prepare('
            SELECT mi.*, mc.name AS category_name
            FROM menu_items mi
            LEFT JOIN menu_categories mc ON mc.id = mi.category_id
            WHERE mi.deleted_at IS NULL
            ORDER BY mc.name, mi.name ASC
        ');
    }
    $stmt->execute();
    $items = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

    foreach ($items as &$r) {
        $r['category'] = $r['category_name'] ?? categoryNameById($conn, $r['category_id']);
        unset($r['category_name']);
    }
    unset($r);
    $items = applyBuiltInMenuImages($items);

    echo json_encode(['success' => true, 'data' => $items]); $conn->close();
}

function getFeaturedItems() {
    $conn = getDB();
    refreshMenuStockFromRecipes($conn);
    $stmt = $conn->prepare('SELECT * FROM menu_items WHERE featured = 1 AND deleted_at IS NULL');
    $stmt->execute();
    $items = applyBuiltInMenuImages(attachCategoryNames($conn, $stmt->get_result()->fetch_all(MYSQLI_ASSOC)));
    echo json_encode(['success' => true, 'data' => $items]); $conn->close();
}

function getArchivedItems() {
    $conn = getDB();
    $stmt = $conn->prepare('SELECT * FROM menu_items WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC');
    $stmt->execute();
    $items = applyBuiltInMenuImages(attachCategoryNames($conn, $stmt->get_result()->fetch_all(MYSQLI_ASSOC)));
    echo json_encode(['success' => true, 'data' => $items]); $conn->close();
}

function createItem() {
    $conn = getDB();
    if (!empty($_POST)) { $name=trim($_POST['name']??''); $category=trim($_POST['category']??''); $price=floatval($_POST['price']??0); $emoji=$_POST['emoji']??''; $featured=intval($_POST['featured']??0); $stock=intval($_POST['stock']??0); $description=trim($_POST['description']??''); }
    else { $data=json_decode(file_get_contents('php://input'),true); $name=trim($data['name']??''); $category=trim($data['category']??''); $price=floatval($data['price']??0); $emoji=$data['emoji']??'☕'; $featured=intval($data['featured']??0); $stock=intval($data['stock']??0); $description=trim($data['description']??''); }
    if (!$name || !$category || !$price) { echo json_encode(['error' => 'Name, category, and price are required.']); return; }

    $categoryId = categoryIdByName($conn, $category);
    if ($categoryId === null) { echo json_encode(['error' => "Unknown category: $category"]); return; }

    $image = handleImageUpload('');
    $stmt = $conn->prepare('INSERT INTO menu_items (name, category_id, price, cost, emoji, image, featured, stock, description) VALUES (?, ?, ?, 0, ?, ?, ?, ?, ?)');
    $stmt->bind_param('sidssiis', $name, $categoryId, $price, $emoji, $image, $featured, $stock, $description);
    if ($stmt->execute()) echo json_encode(['success' => true, 'id' => $stmt->insert_id]);
    else echo json_encode(['error' => 'Failed to create item.']);
    $conn->close();
}

function updateItem() {
    $conn = getDB(); $id = intval($_GET['id'] ?? 0);
    if (!$id) { echo json_encode(['error' => 'Item ID required.']); return; }
    $existing = $conn->prepare('SELECT image FROM menu_items WHERE id=?'); $existing->bind_param('i', $id); $existing->execute();
    $row = $existing->get_result()->fetch_assoc(); $existingImage = $row['image'] ?? '';
    if (!empty($_POST)) { $name=trim($_POST['name']??''); $category=trim($_POST['category']??''); $price=floatval($_POST['price']??0); $emoji=$_POST['emoji']??'☕'; $featured=intval($_POST['featured']??0); $stock=intval($_POST['stock']??0); $description=trim($_POST['description']??''); $removeImage=($_POST['remove_image']??'')==='1'; }
    else { $data=json_decode(file_get_contents('php://input'),true); $name=trim($data['name']??''); $category=trim($data['category']??''); $price=floatval($data['price']??0); $emoji=$data['emoji']??'☕'; $featured=intval($data['featured']??0); $stock=intval($data['stock']??0); $description=trim($data['description']??''); $removeImage=($data['remove_image']??false)===true; }

    $categoryId = categoryIdByName($conn, $category);
    if ($categoryId === null) { echo json_encode(['error' => "Unknown category: $category"]); return; }

    if ($removeImage && $existingImage) { $old = __DIR__ . '/../' . $existingImage; if (file_exists($old)) @unlink($old); $image = ''; } else { $image = handleImageUpload($existingImage); }
    $stmt = $conn->prepare('UPDATE menu_items SET name=?, category_id=?, price=?, emoji=?, image=?, featured=?, stock=?, description=? WHERE id=?');
    $stmt->bind_param('sidssiisi', $name, $categoryId, $price, $emoji, $image, $featured, $stock, $description, $id);
    if ($stmt->execute()) echo json_encode(['success' => true]); else echo json_encode(['error' => 'Failed to update item.']);
    $conn->close();
}

function archiveItem() {
    $conn = getDB(); $id = intval($_GET['id'] ?? 0);
    if (!$id) { echo json_encode(['error' => 'Item ID required.']); return; }
    $stmt = $conn->prepare('UPDATE menu_items SET deleted_at = NOW() WHERE id=? AND deleted_at IS NULL');
    $stmt->bind_param('i', $id);
    if ($stmt->execute() && $stmt->affected_rows > 0) echo json_encode(['success' => true]); else echo json_encode(['error' => 'Failed to archive item.']);
    $conn->close();
}

function restoreItem() {
    $conn = getDB(); $id = intval($_GET['id'] ?? 0);
    if (!$id) { echo json_encode(['error' => 'Item ID required.']); return; }
    $body = json_decode(file_get_contents('php://input'), true); $newCategory = trim($body['category'] ?? '');
    if ($newCategory) {
        $categoryId = categoryIdByName($conn, $newCategory);
        if ($categoryId === null) { echo json_encode(['error' => "Unknown category: $newCategory"]); return; }
        $stmt = $conn->prepare('UPDATE menu_items SET deleted_at = NULL, category_id = ? WHERE id = ?');
        $stmt->bind_param('ii', $categoryId, $id);
    } else {
        $stmt = $conn->prepare('UPDATE menu_items SET deleted_at = NULL WHERE id = ?');
        $stmt->bind_param('i', $id);
    }
    if ($stmt->execute()) echo json_encode(['success' => true]); else echo json_encode(['error' => 'Failed to restore item.']);
    $conn->close();
}

function permanentDeleteItem() {
    $conn = getDB(); $id = intval($_GET['id'] ?? 0);
    if (!$id) { echo json_encode(['error' => 'Item ID required.']); return; }
    $stmt0 = $conn->prepare('SELECT image FROM menu_items WHERE id = ?');
    $stmt0->bind_param('i', $id);
    $stmt0->execute();
    $row = $stmt0->get_result()->fetch_assoc();
    if (!empty($row['image'])) { $path = __DIR__ . '/../' . $row['image']; if (file_exists($path)) @unlink($path); }
    $stmt = $conn->prepare('DELETE FROM menu_items WHERE id=?'); $stmt->bind_param('i', $id);
    if ($stmt->execute()) echo json_encode(['success' => true]); else echo json_encode(['error' => 'Failed to delete.']);
    $conn->close();
}
?>